WITH ranked AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY account_id ORDER BY txn_time DESC NULLS FIRST) AS rn FROM transactions) ranked WHERE rn = 1) SELECT s.id, s.account_id, s.amount, s.merchant, (SELECT MAX(t2.amount) FROM transactions t2 WHERE t2.account_id = s.account_id) AS max_transaction_amount FROM ranked s ORDER BY max_transaction_amount NULLS FIRST, merchant DESC;
